"""TaskLimits.h, from schema/limits.v1.json.

The header these numbers used to live in was the best-explained file in the
firmware library, and that is the whole problem this module has to solve. A
generator that emitted

    #define TG_MAX_STATES 64

would be correct, would pass every test, and would delete the answer to "why 64
and not the 192 that measurably fits" -- which is a question someone will ask, and
which cost a hardware spike to answer. So the rationale travels with the value:
`schema/limits.v1.json` carries it, this emits it, and a value that changes
without its reasoning changing is visible in the diff.

THE SINGLE-SOURCE RULE THIS SATISFIES. `START_LINE_MAX` lives in two repos with
nothing keeping them in sync, and both copies carry comments saying so.
`baudRate` was worse -- per-sketch, so eight copies against the host's one. The
compiler was on its way to becoming a third instance for every capacity number.
After this, a limit has one definition, the firmware header is generated from it,
and `taskgraph codegen --check` fails CI when the two disagree.

Better still, the numbers are ANNOUNCED at connect time in the CAP line, so a
host/firmware mismatch is detected rather than silently truncating a table
(docs/protocol-negotiation.md).
"""

from __future__ import annotations

import textwrap

from taskgraph.registries import limits

BANNER = """/* GENERATED by taskgraph/codegen/limits.py — DO NOT EDIT.
 *
 * Regenerate with `taskgraph codegen`; `taskgraph codegen --check` fails CI when
 * this file is stale. The values, and every word of the reasoning below them,
 * come from schema/limits.v1.json.
 *
 * Change a number THERE. Changing it here is undone by the next codegen run, and
 * in the meantime the compiler and the firmware disagree about the size of the
 * table one of them is about to send the other.
 */
"""

#: Group order in the emitted header. Explicit rather than dict order, because
#: the reading order of a header someone consults under pressure is a design
#: decision, not an artifact of how the JSON was typed.
GROUP_ORDER = ("capacity", "versions", "wire", "durations", "strobes", "watchdog")

GROUP_TITLES = {
    "capacity": "Table capacity",
    "versions": "Versions — all of these travel with every session",
    "wire": "The wire",
    "durations": "Durations",
    "strobes": "Strobe codes and their sentinels",
    "watchdog": "The watchdog — the net the compiler cannot provide",
}


def _block(text: str, indent: str = " *  ") -> list[str]:
    """Prose as a C comment body.

    REFLOWS BY PARAGRAPH, not by line. The schema stores prose as a JSON array
    whose elements are already wrapped for readability in the schema file, and
    wrapping each of those separately produces a ragged column that looks like a
    bug. Blank elements are paragraph breaks and are preserved; everything
    between them is one paragraph joined and re-wrapped.
    """
    out: list[str] = []
    for para in text.split("\n\n"):
        body = " ".join(line.strip() for line in para.splitlines() if line.strip())
        if not body:
            continue
        if out:
            out.append(" *")
        out.extend(indent + line for line in textwrap.wrap(body, width=74))
    return out


def _literal(name: str, value: int) -> str:
    """Sentinels in hex, everything else in decimal.

    Not cosmetic. TG_NO_STROBE is an out-of-band BIT PATTERN, and writing it as
    65535 invites someone to compare it against a duration -- which is exactly
    the collision the firmware's own 32767 sentinel has, sitting one step from a
    legal `lazyDelayMax` (D6). Hex says "this is not a number on the same scale".
    """
    return f"0x{value:04X}" if name.startswith("TG_NO_") else str(value)


def emit_header() -> str:
    lim = limits()
    raw = lim.groups()

    out = [BANNER, "#ifndef TASK_LIMITS_H", "#define TASK_LIMITS_H", ""]

    readme = raw.get("_readme")
    if readme:
        out.append("/* " + "-" * 60)
        out.extend(_block("\n".join(readme)))
        out.append(" */")
        out.append("")

    out.append(f"#define TG_LIMITS_VERSION {lim.version}")
    out.append("")

    seen = set(GROUP_ORDER)
    unknown = [
        g for g in raw
        if isinstance(raw[g], dict) and not g.startswith("_") and g not in seen
    ]
    if unknown:
        #: Fail rather than quietly omit. A group added to the schema and not to
        #: GROUP_ORDER would vanish from the header while still satisfying the
        #: compiler -- the firmware would then be missing a constant nobody
        #: noticed was gone.
        raise AssertionError(
            f"schema/limits.v1.json has group(s) {unknown} that codegen/limits.py does "
            f"not know where to put. Add them to GROUP_ORDER."
        )

    for group in GROUP_ORDER:
        entries = raw.get(group)
        if not entries:
            continue
        out.append("/* " + "=" * 60)
        out.append(f" *  {GROUP_TITLES[group]}")
        gr = entries.get("_group_rationale")
        if gr:
            out.append(" *")
            out.extend(_block("\n".join(gr)))
        out.append(" */")
        out.append("")

        for name, entry in entries.items():
            if name.startswith("_") or not isinstance(entry, dict):
                continue
            text = lim.rationale(name)
            if text:
                out.append("/*")
                out.extend(_block(text))
                measured = entry.get("measured_by")
                if measured:
                    out.append(" *")
                    out.append(f" *  Measured by: {measured}")
                out.append(" */")
            out.append(f"#define {name} {_literal(name, entry['value'])}")
            out.append("")

    out.append("#endif  /* TASK_LIMITS_H */")
    return "\n".join(out) + "\n"
